/* class-table mapper chain: base slice first, then own columns */
static int card_load(sqlite3 *db, int id, CardPayment *out) {
  Payment base;
  if (payment_load(db, id, &base) != 0) return -1;   /* superclass mapper */
  *out = (CardPayment){ .base = base };
  sqlite3_stmt *st;
  sqlite3_prepare_v2(db, "SELECT card_number FROM card_payment WHERE id=?", -1, &st, 0);
  sqlite3_bind_int(st, 1, id);
  if (sqlite3_step(st) == SQLITE_ROW)
    out->card_number = copy_text(sqlite3_column_text(st, 1));
  sqlite3_finalize(st);
  return 0;
}
